`extract_all()` walks the entire tree with `rglob("*")` and doesn’t honor `.graphifyignore` or the existing detect/collect_files filtering (size limits, binary skipping, etc.). On large repos this can make `lsp-import` unexpectedly slow and analyze files Graphify normally excludes. Consider reusing `graphify.detect.collect_files()` (or at least `.graphifyignore`).
```suggestion
        collect_files = None
        try:
            from graphify.detect import collect_files as detect_collect_files
            collect_files = detect_collect_files
        except ImportError:
            collect_files = None

        candidate_files: list[Path] = []
        if collect_files is not None:
            raw_files = None
            try:
                raw_files = collect_files(self.root_path, file_pattern=file_pattern)
            except TypeError:
                try:
                    raw_files = collect_files(self.root_path)
                except TypeError:
                    raw_files = collect_files(str(self.root_path))

            candidate_files = [Path(file_path) for file_path in raw_files]
        else:
            for file_path in self.root_path.rglob("*"):
                if file_path.is_file():
                    rel_path = file_path.relative_to(self.root_path)
                    # Skip common non-source directories
                    if any(part.startswith('.') for part in rel_path.parts):
                        continue
                    if "node_modules" in rel_path.parts or "vendor" in rel_path.parts:
                        continue
                    candidate_files.append(file_path)

        for file_path in candidate_files:
            if not file_path.is_file():
                continue

            if file_pattern is not None:
                try:
                    rel_path = file_path.relative_to(self.root_path)
                except ValueError:
                    rel_path = file_path
                if not rel_path.match(file_pattern):
                    continue

            calls = self.extract_from_file(file_path)
            all_calls.extend(calls)
